import styles from "./flippable-item.module.less";
import { multipleClassNames } from "@/core/helpers";

type FlippableItemProps = {
  /** Exactly two children: the front and the back face */
  children: [React.ReactNode, React.ReactNode];
  /** `true` rotates to the second child (the back) */
  isFlipped: boolean;
  className?: string;
};

export const FlippableItem = ({ children, isFlipped, className }: FlippableItemProps) => {
  return (
    <div className={multipleClassNames(className, styles.flipCard)}>
      <div className={multipleClassNames(styles.flipCardInner, isFlipped && styles.flipped)}>
        <div className={styles.flipCardFront}>{children[0]}</div>
        <div className={styles.flipCardBack}>{children[1]}</div>
      </div>
    </div>
  );
};
