import { Meta, StoryObj } from "@storybook/react";
import { ReactNode, useState } from "react";
import { FlippableItem } from "./flippable-item";
import styles from "./flippable-item-stories.module.less";
import { Button } from "@/core/components/primitives/parks-button/parks-button";
import { ShowcaseLayout, Variant, showcaseParameters, desktopOnlyMode } from "@/storybook/preview";

const frontAndBack: [ReactNode, ReactNode] = [
  <div key="front" style={{ backgroundColor: "lightblue", height: "100%", textAlign: "center" }}>
    Front
  </div>,
  <div key="back" style={{ backgroundColor: "lightgreen", height: "100%", textAlign: "center" }}>
    Back
  </div>,
];

const meta = {
  title: "Primitives/Flippable Item",
  component: FlippableItem,
  parameters: {
    chromatic: desktopOnlyMode,
    docs: {
      description: {
        component:
          "3D flip card that rotates between two faces. Takes exactly two children - the front and " +
          "the back - and a controlled `isFlipped` prop that decides which one is shown. The flip " +
          "itself is a CSS transition, so toggling the prop animates the rotation.",
      },
    },
  },
  argTypes: {
    // The two faces are arbitrary JSX - not meaningful to edit as a control.
    children: { table: { disable: true } },
  },
  args: {
    children: frontAndBack,
    isFlipped: false,
    className: styles.card,
  },
  // The component is fully controlled, so the story owns the flip state via the button.
  render: function StoryComponent(args) {
    const [isFlipped, setIsFlipped] = useState(args.isFlipped);
    return (
      <div style={{ display: "flex", flexDirection: "column", gap: "2rem", alignItems: "center" }}>
        <FlippableItem {...args} isFlipped={isFlipped} />
        <Button onClick={() => setIsFlipped((prev) => !prev)} label="Flip it!" />
      </div>
    );
  },
} satisfies Meta<typeof FlippableItem>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const VariantIsFlipped: Story = {
  parameters: { ...showcaseParameters, chromatic: desktopOnlyMode },
  render: (args) => (
    <ShowcaseLayout title="isFlipped" variantType="prop">
      <Variant label="false (front)">
        <FlippableItem {...args} isFlipped={false} />
      </Variant>
      <Variant label="true (back)">
        <FlippableItem {...args} isFlipped={true} />
      </Variant>
    </ShowcaseLayout>
  ),
};
